const crypto = require('crypto');
const item = $input.first().json;
const body = item.body ?? item;
const canon = JSON.stringify(body);
const hash = crypto.createHash('sha3-512').update(canon).digest('hex');
const nodeId = String(body.node_id || body.nodeId || 'unknown');
const base = String($env.GAIACHAIN_NODE_VALIDATE_URL || $env.GAIACHAIN_VALIDATE_URL || '').trim();
let gaia = { skipped: true, reason: 'GAIACHAIN_NODE_VALIDATE_URL / GAIACHAIN_VALIDATE_URL no configurada' };
if (base) {
  const r = await fetch(base, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ nodeId, hash, ts: new Date().toISOString() }),
  });
  const t = await r.text();
  let parsed;
  try { parsed = JSON.parse(t); } catch { parsed = { raw: t }; }
  gaia = { http_status: r.status, response: parsed };
}
return [{ json: { nodeId, config_hash_sha3_512: hash, gaia } }];
